// Generated quiz scenarios. All answers are calculated with native JavaScript.
// `code` ends with the expression whose value the learner should predict.
const literal = value => value === undefined ? "undefined" : Array.isArray(value) ? `[${value.map(literal).join(", ")}]` : value && typeof value === "object" ? `{${Object.entries(value).map(([k,v])=>`${JSON.stringify(k)}: ${literal(v)}`).join(", ")}}` : JSON.stringify(value);
const fingerprint = value => value === undefined ? "undefined" : JSON.stringify(value);
function question(code, value, candidates, explanation) {
  const seen = new Set([fingerprint(value)]), distractors = [];
  const extras = Array.isArray(value) ? [[], [value], value.length, [...value].reverse(), null, undefined] : typeof value === "boolean" ? [!value, 0, 1, undefined, []] : typeof value === "string" ? [value + "!", value.slice(1), value.toUpperCase(), value.toLowerCase(), "", null] : typeof value === "number" ? [value + 1, value - 1, 0, String(value), null] : [null, [], 0, "undefined", false];
  for (const candidate of [...candidates, ...extras]) {
    const key = fingerprint(candidate);
    if (!seen.has(key)) { seen.add(key); distractors.push(candidate); }
    if (distractors.length === 3) break;
  }
  return { code, value, distractors, explanation };
}
const expression = (code, value, distractors, explanation) => question(code, value, distractors, explanation);
const program = (body, last, value, distractors, explanation) => question(`${body}\n${last}`, value, distractors, explanation);
const numbers = c => Array.from({length:c.int(3,5)},()=>c.int(-6,15));
const names = c => c.sample(["Ada", "Lin", "Maya", "Noah", "Ira", "Zoe", "Kai", "Leo"],c.int(3,5));
const words = c => c.sample(["apple", "river", "sun", "stone", "moon", "leaf", "rain", "cloud"],c.int(3,5));
const objects = c => names(c).map(name=>({name,score:c.int(0,20)}));
const dict = c => Object.fromEntries(c.sample(["score", "level", "count", "bonus", "rank"],3).map(k=>[k,c.int(0,30)]));

